using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

/// <summary>
/// MCP tools that wrap the JSONPlaceholder REST API.
/// Uses constructor injection — the SDK resolves IHttpClientFactory and ILogger
/// from DI automatically. These parameters never appear in the tool schema.
/// </summary>
[McpServerToolType]
public class PostsApiTools(IHttpClientFactory httpFactory, ILogger<PostsApiTools> logger)
{
    private static readonly JsonSerializerOptions JsonOptions = new() { WriteIndented = true };

    [McpServerTool, Description("Get a blog post by its numeric ID.")]
    public async Task<string> GetPost(
        [Description("The post ID (1-100).")] int id,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching post {Id}", id);
        var client = httpFactory.CreateClient("api");
        var post = await client.GetFromJsonAsync<JsonElement>(
            $"/posts/{id}", cancellationToken);
        return JsonSerializer.Serialize(post, JsonOptions);
    }

    [McpServerTool, Description("List all posts, optionally filtered by user ID.")]
    public async Task<string> ListPosts(
        [Description("Filter posts to this user ID. Omit for all posts.")] int? userId = null,
        CancellationToken cancellationToken = default)
    {
        var client = httpFactory.CreateClient("api");
        var url = userId.HasValue ? $"/posts?userId={userId}" : "/posts";
        var posts = await client.GetFromJsonAsync<JsonElement>(url, cancellationToken);
        return JsonSerializer.Serialize(posts, JsonOptions);
    }

    [McpServerTool, Description("List all comments on a specific post.")]
    public async Task<string> GetComments(
        [Description("The post ID to get comments for.")] int postId,
        CancellationToken cancellationToken = default)
    {
        var client = httpFactory.CreateClient("api");
        var comments = await client.GetFromJsonAsync<JsonElement>(
            $"/posts/{postId}/comments", cancellationToken);
        return JsonSerializer.Serialize(comments, JsonOptions);
    }

    [McpServerTool(Destructive = false, ReadOnly = true),
     Description("Search posts by title keyword.")]
    public async Task<string> SearchPosts(
        [Description("Keyword to search for in post titles.")] string keyword,
        CancellationToken cancellationToken = default)
    {
        var client = httpFactory.CreateClient("api");
        var posts = await client.GetFromJsonAsync<JsonElement>("/posts", cancellationToken);

        var matches = posts.EnumerateArray()
            .Where(p => p.GetProperty("title").GetString()
                ?.Contains(keyword, StringComparison.OrdinalIgnoreCase) == true)
            .ToList();

        return JsonSerializer.Serialize(matches, JsonOptions);
    }
}

